def get_evaluation_targets() -> list[dict]:
    """Return a defensive copy of all reference annotations."""
    return deepcopy(_EVAL)


def get_target_by_filename(filename: str) -> dict:
    """Return the reference annotation for one image filename."""
    name = Path(filename).name
    for target in _EVAL:
        if target["filename"] == name:
            return deepcopy(target)
    raise KeyError(f"No evaluation target found for: {filename}")


if __name__ == "__main__":
    print(f"Loaded {len(_EVAL)} external evaluation targets.")
